export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  template?: string;
  layout?: string;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  slug: string;
  html?: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  incremental?: boolean;
  clean?: boolean;
}

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port: number;
}

export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void;
  beforeBuild?(ctx: PluginContext): void;
  onFile?(page: Page, ctx: PluginContext): void;
  afterBuild?(ctx: PluginContext): void;
  onEnd?(ctx: PluginContext): void;
}

export interface PluginContext extends Record<string, any> {
  options: BuildOptions;
  pages: Page[];
}

export interface BuildStats {
  pagesBuilt: number;
  pagesSkipped: number;
  totalPages: number;
}

export interface CacheEntry {
  contentHash: string;
  templateHash: string;
  html: string;
}

export interface CacheManifest {
  templateHash: string;
  pages: Record<string, CacheEntry>;
}

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { CacheManifest, CacheEntry, Frontmatter } from './types';

export function computeHash(content: string): string {
  return crypto.createHash('sha256').update(content).digest('hex');
}

export function computeTemplateHash(templatesDir: string): string {
  const absDir = path.resolve(templatesDir);
  if (!fs.existsSync(absDir)) {
    return '';
  }
  const hashes: string[] = [];
  collectTemplateHashes(absDir, hashes);
  hashes.sort();
  return computeHash(hashes.join(''));
}

function collectTemplateHashes(dir: string, hashes: string[]): void {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      collectTemplateHashes(fullPath, hashes);
    } else if (entry.isFile() && entry.name.endsWith('.hbs')) {
      const content = fs.readFileSync(fullPath, 'utf-8');
      hashes.push(computeHash(content));
    }
  }
}

export class CacheManager {
  private manifestPath: string;
  private manifest: CacheManifest;

  constructor(manifestPath: string) {
    this.manifestPath = manifestPath;
    this.manifest = { templateHash: '', pages: {} };
  }

  load(): void {
    try {
      if (fs.existsSync(this.manifestPath)) {
        const raw = fs.readFileSync(this.manifestPath, 'utf-8');
        const parsed = JSON.parse(raw);
        if (parsed && parsed.pages) {
          this.manifest = parsed;
        }
      }
    } catch {
      this.manifest = { templateHash: '', pages: {} };
    }
  }

  save(): void {
    const dir = path.dirname(this.manifestPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(this.manifestPath, JSON.stringify(this.manifest, null, 2), 'utf-8');
  }

  clear(): void {
    this.manifest = { templateHash: '', pages: {} };
    if (fs.existsSync(this.manifestPath)) {
      fs.unlinkSync(this.manifestPath);
    }
  }

  get(filePath: string, contentHash: string, templateHash: string): CacheEntry | null {
    if (this.manifest.templateHash !== templateHash) {
      return null;
    }
    const entry = this.manifest.pages[filePath];
    if (!entry || entry.contentHash !== contentHash || entry.templateHash !== templateHash) {
      return null;
    }
    return entry;
  }

  set(filePath: string, contentHash: string, templateHash: string, html: string): void {
    this.manifest.pages[filePath] = {
      contentHash,
      templateHash,
      html,
    };
  }

  updateTemplateHash(templateHash: string): void {
    this.manifest.templateHash = templateHash;
  }
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { Page, BuildOptions, Frontmatter, PluginContext, BuildStats } from './types';
import { loadPlugins } from './plugin';
import { computeHash, computeTemplateHash, CacheManager } from './cache';

function readPages(contentDir: string): Page[] {
  const absDir = path.resolve(contentDir);
  if (!fs.existsSync(absDir)) {
    throw new Error(`Content directory not found: ${absDir}`);
  }

  const entries = fs.readdirSync(absDir, { withFileTypes: true });
  const pages: Page[] = [];

  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith('.md')) {
      continue;
    }

    const filePath = path.join(absDir, entry.name);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const parsed = matter(raw);

    const slug = entry.name.replace(/\.md$/, '');
    const rawData = parsed.data as Record<string, unknown>;

    if (!rawData.title || typeof rawData.title !== 'string') {
      throw new Error(`Missing title in frontmatter for: ${entry.name}`);
    }

    let date: string | undefined;
    if (rawData.date instanceof Date) {
      date = rawData.date.toISOString().split('T')[0];
    } else if (typeof rawData.date === 'string') {
      date = rawData.date;
    }

    let tags: string[] | undefined;
    if (Array.isArray(rawData.tags)) {
      tags = rawData.tags.map((t) => String(t));
    }

    const frontmatter: Frontmatter = {
      title: rawData.title,
      date,
      tags,
    };

    if (rawData.template && typeof rawData.template === 'string') {
      frontmatter.template = rawData.template;
    }
    if (rawData.layout === false || rawData.layout === '') {
      frontmatter.layout = '';
    } else if (rawData.layout && typeof rawData.layout === 'string') {
      frontmatter.layout = rawData.layout;
    }

    pages.push({
      frontmatter,
      content: parsed.content,
      slug,
    });
  }

  pages.sort((a, b) => {
    if (a.frontmatter.date && b.frontmatter.date) {
      return new Date(b.frontmatter.date).getTime() - new Date(a.frontmatter.date).getTime();
    }
    if (a.frontmatter.date) return -1;
    if (b.frontmatter.date) return 1;
    return a.frontmatter.title.localeCompare(b.frontmatter.title);
  });

  return pages;
}

export function build(options: BuildOptions): BuildStats {
  const plugins = loadPlugins();

  const ctx: PluginContext = { options, pages: [] };

  for (const plugin of plugins) {
    plugin.onStart?.(ctx);
  }

  const templatesDir = path.resolve(options.templatesDir || './templates');
  const templateHash = computeTemplateHash(templatesDir);

  const contentDir = path.resolve(options.contentDir);
  const cacheFile = path.resolve(contentDir, '..', '.ssg-cache.json');
  const cacheManager = new CacheManager(cacheFile);

  const incremental = !!options.incremental;
  const clean = !!options.clean;

  if (clean) {
    cacheManager.clear();
  }

  if (incremental && !clean) {
    cacheManager.load();
  }

  for (const plugin of plugins) {
    plugin.beforeBuild?.(ctx);
  }

  const pages = readPages(options.contentDir);
  ctx.pages = pages;

  const absOutputDir = path.resolve(options.outputDir);
  fs.mkdirSync(absOutputDir, { recursive: true });

  const absContentDir = path.resolve(options.contentDir);
  let pagesBuilt = 0;
  let pagesSkipped = 0;

  for (const page of pages) {
    const filePath = path.join(absContentDir, `${page.slug}.md`);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const contentHash = computeHash(raw);

    if (incremental && !clean) {
      const cached = cacheManager.get(filePath, contentHash, templateHash);
      if (cached) {
        page.html = cached.html;
        pagesSkipped++;
        continue;
      }
    }

    for (const plugin of plugins) {
      plugin.onFile?.(page, ctx);
    }
    pagesBuilt++;

    if (incremental && !clean && page.html !== undefined) {
      cacheManager.set(filePath, contentHash, templateHash, page.html);
    }
  }

  for (const page of pages) {
    if (page.html !== undefined) {
      const outPath = path.join(absOutputDir, `${page.slug}.html`);
      fs.writeFileSync(outPath, page.html, 'utf-8');
    }
  }

  if (ctx._renderIndex) {
    const pagesData = pages.map((page) => ({
      title: page.frontmatter.title,
      slug: page.slug,
      date: page.frontmatter.date || null,
    }));
    const indexHtml = ctx._renderIndex(pagesData);
    fs.writeFileSync(path.join(absOutputDir, 'index.html'), indexHtml, 'utf-8');
  }

  for (const plugin of plugins) {
    plugin.afterBuild?.(ctx);
  }

  for (const plugin of plugins) {
    plugin.onEnd?.(ctx);
  }

  if (incremental && !clean) {
    cacheManager.updateTemplateHash(templateHash);
    cacheManager.save();
  }

  return {
    pagesBuilt,
    pagesSkipped,
    totalPages: pages.length,
  };
}

#!/usr/bin/env node

import { build } from './build';
import { serve } from './serve';
import { BuildOptions, ServeOptions } from './types';

function parseBuildArgs(argv: string[]): BuildOptions {
  const contentIdx = argv.indexOf('--content');
  const outputIdx = argv.indexOf('--output');
  const templatesIdx = argv.indexOf('--templates');
  const incremental = argv.includes('--incremental');
  const clean = argv.includes('--clean');

  return {
    contentDir: contentIdx !== -1 ? argv[contentIdx + 1] : './content',
    outputDir: outputIdx !== -1 ? argv[outputIdx + 1] : './dist',
    templatesDir: templatesIdx !== -1 ? argv[templatesIdx + 1] : undefined,
    incremental,
    clean,
  };
}

function parseServeArgs(argv: string[]): ServeOptions {
  const buildOptions = parseBuildArgs(argv);
  const portIdx = argv.indexOf('--port');
  const port = portIdx !== -1 ? parseInt(argv[portIdx + 1], 10) : 3000;
  return {
    contentDir: buildOptions.contentDir,
    outputDir: buildOptions.outputDir,
    templatesDir: buildOptions.templatesDir,
    port: isNaN(port) ? 3000 : port,
  };
}

const args = process.argv.slice(2);
const command = args[0];

if (command === 'build') {
  const options = parseBuildArgs(args);
  try {
    const stats = build(options);
    const builtMsg = `Pages: ${stats.pagesBuilt} built`;
    const skippedMsg = stats.pagesSkipped > 0 ? `, ${stats.pagesSkipped} skipped (unchanged)` : '';
    const totalMsg = `, ${stats.totalPages} total`;
    console.log(`Site built successfully in ${options.outputDir}`);
    console.log(builtMsg + skippedMsg + totalMsg);
  } catch (err) {
    console.error('Error building site:', (err as Error).message);
    process.exit(1);
  }
} else if (command === 'serve') {
  const options = parseServeArgs(args);
  serve(options);
} else {
  console.log('Usage: npx ssg build [--content <dir>] [--output <dir>] [--templates <dir>] [--incremental] [--clean]');
  console.log('       npx ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]');
  process.exit(0);
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { Plugin, ServeOptions } from '../types';
import { build } from '../build';

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const mimeTypes: Record<string, string> = {
    '.html': 'text/html',
    '.htm': 'text/html',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
  };
  return mimeTypes[ext] || 'application/octet-stream';
}

function injectReloadScript(html: string, port: number): string {
  const script = `<script>(function(){var s=new WebSocket('ws://localhost:${port}/__livereload');s.onmessage=function(m){if(m.data==='reload')window.location.reload()};})();</script>`;
  if (html.includes('</body>')) {
    return html.replace('</body>', script + '</body>');
  }
  return html + script;
}

export const DevServerPlugin: Plugin = {
  name: 'dev-server',
};

export function createDevServer(options: ServeOptions): http.Server {
  const { contentDir, outputDir, templatesDir, port } = options;
  const resolvedOutputDir = path.resolve(outputDir);
  const resolvedTemplatesDir = path.resolve(templatesDir || './templates');

  build({ contentDir, outputDir, templatesDir, incremental: true });

  const server = http.createServer((req, res) => {
    const url = req.url || '/';
    const reqPath = url === '/' ? 'index.html' : url;
    const relativePath = reqPath.startsWith('/') ? reqPath.slice(1) : reqPath;
    const filePath = path.join(resolvedOutputDir, relativePath);

    const resolved = path.resolve(filePath);
    if (!resolved.startsWith(resolvedOutputDir + path.sep) && resolved !== resolvedOutputDir) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }

    const mimeType = getMimeType(resolved);

    if (mimeType === 'text/html') {
      let html = fs.readFileSync(resolved, 'utf-8');
      html = injectReloadScript(html, port);
      res.writeHead(200, { 'Content-Type': mimeType });
      res.end(html);
    } else {
      const content = fs.readFileSync(resolved);
      res.writeHead(200, { 'Content-Type': mimeType });
      res.end(content);
    }
  });

  const wss = new WebSocketServer({ noServer: true });

  server.on('upgrade', (request, socket, head) => {
    const { pathname } = new URL(request.url || '', `http://localhost:${port}`);
    if (pathname === '/__livereload') {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit('connection', ws, request);
      });
    } else {
      socket.destroy();
    }
  });

  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => {
      clients.delete(ws);
    });
  });

  const watchPaths = [
    path.resolve(contentDir),
    resolvedTemplatesDir,
  ];

  let rebuildTimeout: ReturnType<typeof setTimeout> | null = null;

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 200,
      pollInterval: 100,
    },
  });

  watcher.on('all', (event, filePath) => {
    console.log(`[change] ${event}: ${filePath}`);
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        build({ contentDir, outputDir, templatesDir, incremental: true });
        console.log('[rebuilt]');
        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch (err) {
        console.error('[build error]', (err as Error).message);
      }
    }, 150);
  });

  server.on('close', () => {
    watcher.close();
    wss.close();
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}/`);
  });

  return server;
}

